pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testRegression_property() public {
        c.SetMinSum(0);
        address log = address(new LogFile());
        c.SetLogFile(log);
        c.Initialized();
        address alice = address(0x1);
        vm.deal(alice, 1000);
        vm.prank(alice);
        c.Deposit{value: 1000}();
        address bob = address(0x2);
        vm.deal(bob, 200);
        vm.prank(bob);
        c.Deposit{value: 100}();
        vm.prank(bob);
        c.Collect(100);
        assertTrue(c.balances(bob) == 0);
    }
}

contract LogFile
{
    struct Message
    {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;

    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data)
    public
    {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
